#include <zephyr/nvmem.h>
#include <zephyr/drivers/nvmem.h>
#include <zephyr/sys/math_extras.h>

int nvmem_cell_write(const struct nvmem_cell *cell, const void *buf, size_t offset, size_t len)
{
	size_t end_offset;

	if (cell == NULL || cell->dev == NULL || buf == NULL) {
		return -EINVAL;
	}

	if (nvmem_cell_is_read_only(cell)) {
		return -EROFS;
	}

	if (size_add_overflow(offset, len, &end_offset) || end_offset > cell->size) {
		return -EINVAL;
	}

	const struct nvmem_driver_api *api = (const struct nvmem_driver_api *)cell->dev->api;

	if (api->write == NULL) {
		return -ENOTSUP;
	}

	return api->write(cell->dev, cell->offset + offset, buf, len);
}

